using System.Diagnostics;
using System.Text;
using System.Text.Json;
using NovaForge.Core;
namespace NovaForge.Automation;
public sealed class SandboxFeature
{
 public string Edition {get;set;}="";public int? State {get;set;}public bool Hypervisor {get;set;}public bool? FirmwareVirtualization {get;set;}
 public bool Supported=>Edition.StartsWith("Professional",StringComparison.OrdinalIgnoreCase)||Edition.StartsWith("Enterprise",StringComparison.OrdinalIgnoreCase)||Edition.StartsWith("Education",StringComparison.OrdinalIgnoreCase);
 public string Status=>!Supported?"Windows Sandbox benötigt eine unterstützte Pro-/Enterprise-/Education-Edition (erkannt: "+Edition+").":State==null?"Windows-Sandbox-Feature ist in dieser Windows-Installation nicht verfügbar.":!Hypervisor&&FirmwareVirtualization==false?"Virtualisierung im BIOS/UEFI aktivieren; Windows Sandbox ist noch nicht nutzbar.":State==1?(SandboxSessions.Available?"Windows Sandbox ist aktiviert. Aufnahme kann gestartet werden.":"Sandbox-Feature aktiviert; Startprogramm fehlt noch. Windows neu starten und Installation prüfen."):"Windows Sandbox ist vorhanden, aber deaktiviert. Über den Aktivierungsbutton einschalten; danach bei Bedarf Windows neu starten.";
 public void ValidateActivation(){if(!Supported||State==null||(!Hypervisor&&FirmwareVirtualization==false))throw new InvalidOperationException(Status);}
 public static async Task<SandboxFeature> Read(CancellationToken ct=default){const string script="$f=Get-CimInstance Win32_OptionalFeature -Filter \"Name='Containers-DisposableClientVM'\"; $c=Get-CimInstance Win32_ComputerSystem; $p=Get-CimInstance Win32_Processor | Select-Object -First 1; [pscustomobject]@{Edition=(Get-ItemProperty 'HKLM:\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion').EditionID;State=$f.InstallState;Hypervisor=$c.HypervisorPresent;FirmwareVirtualization=$p.VirtualizationFirmwareEnabled} | ConvertTo-Json -Compress";using var process=Process.Start(new ProcessStartInfo(IsoBuilder.PowerShell){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=Environment.GetFolderPath(Environment.SpecialFolder.System),RedirectStandardOutput=true,RedirectStandardError=true,Arguments="-NoProfile -NonInteractive -EncodedCommand "+Convert.ToBase64String(Encoding.Unicode.GetBytes(script))})??throw new IOException("Windows-Feature-Status kann nicht gelesen werden.");var output=process.StandardOutput.ReadToEndAsync();var error=process.StandardError.ReadToEndAsync();using var timeout=CancellationTokenSource.CreateLinkedTokenSource(ct);timeout.CancelAfter(TimeSpan.FromSeconds(15));try{await process.WaitForExitAsync(timeout.Token);}catch{if(!process.HasExited)process.Kill(true);throw;}if(process.ExitCode!=0)throw new IOException("Windows-Feature-Abfrage fehlgeschlagen: "+await error);return JsonSerializer.Deserialize<SandboxFeature>(await output,Project.JsonOptions)??throw new IOException("Windows-Feature-Status fehlt.");}
}
